+  const { app, repository } = setup();
+  const responses = [
+    await request(app).get(`/api/todos/${id}`),
+    await request(app).patch(`/api/todos/${id}`).send({ title: 'New' }),
+    await request(app).delete(`/api/todos/${id}`),
+  ];
